import{_ as e,o,c as a,a3 as d}from"./chunks/framework.WFmvnizL.js";const r="/assets/1.BP35IDvP.png",l="/assets/2.CDwiG492.png",s="/assets/3.BovmuO_m.png",c="/assets/4.DPaad1lP.png",n="/assets/5.CdxvjrYx.png",i="/assets/6.B6hW8_P0.png",f=JSON.parse('{"title":"内置备份与恢复","description":"使用哪吒监控 Dashboard 内置的加密备份与恢复：配置 S3 兼容存储（以 Cloudflare R2 为例）、保管备份密码与恢复密钥、定时备份与保留份数、下载，以及在原主机或新主机上恢复。","frontmatter":{"description":"使用哪吒监控 Dashboard 内置的加密备份与恢复：配置 S3 兼容存储（以 Cloudflare R2 为例）、保管备份密码与恢复密钥、定时备份与保留份数、下载，以及在原主机或新主机上恢复。","outline":"deep"},"headers":[],"relativePath":"guide/backup.md","filePath":"guide/backup.md","lastUpdated":1795785361000}'),p={name:"guide/backup.md"};function h(g,t,u,b,m,_){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="内置备份与恢复" tabindex="-1">内置备份与恢复 <a class="header-anchor" href="#内置备份与恢复" aria-label="Permalink to &quot;内置备份与恢复&quot;">​</a></h1><p>Dashboard 可以在后台直接备份自己的数据，并上传到 S3 兼容存储（AWS S3、Cloudflare R2、MinIO 等）。备份在面板运行时生成，不需要停机；文件在上传前加密。恢复可以选择存储中的备份，也可以上传备份文件，并且在全新安装的面板上也能使用。</p><p><strong>入口：</strong> 以管理员身份登录后台，点击头像 → 系统设置 → <strong>备份</strong> 标签页。只有管理员可以使用，API Token 无法调用备份接口。</p><div class="tip custom-block"><p class="custom-block-title">适用版本</p><p>本功能需要 Dashboard v2.8.0 及以上版本。更早的版本请使用<a href="/guide/q5.html">手动迁移、备份和恢复</a>。</p></div><h2 id="备份包含什么" tabindex="-1">备份包含什么 <a class="header-anchor" href="#备份包含什么" aria-label="Permalink to &quot;备份包含什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包含</th><th>不包含</th></tr></thead><tbody><tr><td>面板数据库（用户、服务器、服务、告警、任务、通知、DDNS 等全部设置）</td><td>监控时序数据（TSDB）</td></tr><tr><td><code>data/config.yaml</code></td><td>Compose 文件、反向代理配置、证书、systemd/OpenRC 服务文件等部署文件</td></tr><tr><td></td><td>备份功能自身的设置（<code>data/backup.yaml</code>）</td></tr></tbody></table><p>需要保留 TSDB 历史数据或部署文件时，另行备份，或使用<a href="/guide/q5.html">手动迁移方法</a>。</p><p>备份文件扩展名为 <code>.nzbak</code>。备份只在数据目录下临时生成，上传完成后删除，Docker 部署不需要额外挂载目录。</p><h2 id="首次设置" tabindex="-1">首次设置 <a class="header-anchor" href="#首次设置" aria-label="Permalink to &quot;首次设置&quot;">​</a></h2><p>备份页按顺序引导三步：<strong>S3 存储 → 备份密码 → 定时计划</strong>。存储和密码都设置好后，才能备份。</p><p><img src="'+r+'" alt="首次设置"></p><h3 id="_1-配置-s3-存储" tabindex="-1">1. 配置 S3 存储 <a class="header-anchor" href="#_1-配置-s3-存储" aria-label="Permalink to &quot;1. 配置 S3 存储&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Endpoint</td><td>存储服务地址，必须以 <code>https://</code> 开头，不能带路径。</td></tr><tr><td>Bucket</td><td>存放备份的 bucket，需要预先创建。</td></tr><tr><td>Region</td><td>区域。服务商没有区域概念时按其文档填写（R2 填 <code>auto</code>）。</td></tr><tr><td>对象键前缀</td><td>默认 <code>nezha-backup/</code>，留空时也使用默认值。只能包含字母、数字、<code>/</code>、<code>_</code> 和 <code>-</code>。<strong>多个面板共用一个 bucket 时，必须使用不同的前缀</strong>，否则保留份数清理会删掉对方的备份。</td></tr><tr><td>Path-style 寻址</td><td>默认开启。只有服务仅支持 <code>bucket.endpoint</code> 形式的虚拟主机寻址时才关闭。</td></tr><tr><td>Access Key ID / Secret Access Key</td><td>访问密钥。Secret 保存后不会再显示；修改 Endpoint 或 Bucket 时需要重新填写。</td></tr></tbody></table><p>首次配置时，必须先通过 <strong>测试连接</strong> 才能保存；修改已有配置时，也建议先测试再保存。测试会在前缀下写入一个临时对象，读回校验后删除，所以至少需要读、写和删除对象的权限。备份列表和保留份数清理还要列出前缀下的对象，因此日常使用时密钥还需要列出对象的权限。</p><h4 id="示例-cloudflare-r2" tabindex="-1">示例：Cloudflare R2 <a class="header-anchor" href="#示例-cloudflare-r2" aria-label="Permalink to &quot;示例：Cloudflare R2&quot;">​</a></h4><ol><li>在 Cloudflare 控制台的 <strong>R2</strong> 中创建一个 bucket，例如 <code>nezha-backup</code>。</li><li>在 R2 的 <strong>Manage API tokens</strong> 中创建 API token：权限选 <strong>Object Read &amp; Write</strong>，范围只指定这个 bucket。创建后记下 <strong>Access Key ID</strong> 和 <strong>Secret Access Key</strong>，以及页面上显示的 S3 endpoint。</li><li>在备份页填写： <ul><li>Endpoint：<code>https://&lt;ACCOUNT_ID&gt;.r2.cloudflarestorage.com</code></li><li>Bucket：<code>nezha-backup</code></li><li>Region：<code>auto</code></li><li>对象键前缀：保持默认 <code>nezha-backup/</code>，或按需修改</li><li>Path-style 寻址：保持默认开启，R2 两种寻址方式都支持</li></ul></li><li>点击 <strong>测试连接</strong>，通过后保存。</li></ol><p><img src="'+l+'" alt="填写 R2 存储并通过连接测试"></p><p>不要使用账户级的全权限令牌；令牌只授予这一个 bucket 的对象读写权限即可。</p><h3 id="_2-设置备份密码并保存恢复密钥" tabindex="-1">2. 设置备份密码并保存恢复密钥 <a class="header-anchor" href="#_2-设置备份密码并保存恢复密钥" aria-label="Permalink to &quot;2. 设置备份密码并保存恢复密钥&quot;">​</a></h3><p>备份密码至少 12 位。设置时还需要输入你的登录密码，只使用 OAuth 登录、没有本地密码的账号需要在 10 分钟内重新登录过；因为设置备份密码的人可以解密之后的所有备份。设置密码时，面板会生成一对密钥：</p><ul><li>备份用公钥加密，所以定时备份不需要输入密码；</li><li>私钥只以被备份密码保护的形式保存，服务端不保存密码明文；</li><li>同时生成一个<strong>恢复密钥</strong>，只显示一次，可以复制或下载为 <code>.txt</code>，勾选“我已妥善保存恢复密钥”后才能关闭。它能代替密码恢复同一密钥下的所有备份。</li></ul><p><img src="'+s+'" alt="保存恢复密钥"></p><div class="danger custom-block"><p class="custom-block-title">请妥善保管</p><p>忘记备份密码、又没有恢复密钥时，备份<strong>无法恢复</strong>，任何人都无法解密。</p><ul><li>把备份密码存进密码管理器；</li><li>恢复密钥离线保管，与备份文件分开存放；</li><li>不要把恢复密钥和备份放在同一个 bucket 里。</li></ul></div><p><strong>修改密码：</strong> 密钥不变，只更换保护私钥的密码。新备份使用新密码；旧备份可以用旧密码恢复，在本面板上用新密码也能恢复。</p><p><strong>重置密码：</strong> 生成新的密钥，只在忘记密码或怀疑密码泄露时使用。重置后，之前的备份在列表中标为 <strong>旧密钥</strong>，只能用旧密码或旧恢复密钥恢复。重置需要输入 <code>RESET</code> 确认，并和设置密码一样验证登录密码。重置前请确认手里还有其中之一，或者已经不需要这些备份。</p><h3 id="_3-定时备份与保留份数" tabindex="-1">3. 定时备份与保留份数 <a class="header-anchor" href="#_3-定时备份与保留份数" aria-label="Permalink to &quot;3. 定时备份与保留份数&quot;">​</a></h3><ul><li>定时计划使用 6 段 cron 表达式（秒在最前），时区与计划任务相同。默认 <code>0 0 3 * * *</code>，即每天 03:00。</li><li><strong>保留定时备份份数</strong>默认 7 份，可设为 1 到 100。超出的定时备份在新的定时备份完成后自动删除。</li><li>保留份数<strong>只清理定时备份</strong>。手动备份不会被自动删除；“恢复前自动”生成的备份保留最近 3 份。</li><li>上传失败会自动重试；仍然失败时，列表中显示为“失败”并附带原因。</li></ul><h2 id="手动备份与下载" tabindex="-1">手动备份与下载 <a class="header-anchor" href="#手动备份与下载" aria-label="Permalink to &quot;手动备份与下载&quot;">​</a></h2><p>在备份列表点击 <strong>立即备份</strong> 即可。列表从已配置的 bucket 中读取，显示每份备份的创建时间、大小、触发方式（手动、定时、恢复前自动）、状态、面板版本和 SHA-256。</p><p><img src="'+c+'" alt="备份列表"></p><p>点击 <strong>下载</strong> 可以把 <code>.nzbak</code> 文件保存到本地。下载由面板转发，不会暴露存储的地址和密钥。下载的文件仍然是加密的，可以离线保存，之后通过上传恢复。</p><p>不需要的备份可以勾选后删除，删除后无法找回。</p><h2 id="恢复" tabindex="-1">恢复 <a class="header-anchor" href="#恢复" aria-label="Permalink to &quot;恢复&quot;">​</a></h2><p>恢复会覆盖当前的数据库和配置，然后重启面板，所有用户都会退出登录。恢复分两步，第一步不会改动任何数据。</p><div class="warning custom-block"><p class="custom-block-title">面板需要由守护进程管理</p><p>执行恢复后，面板会退出，并在下次启动时换入数据。官方安装方式（Docker 的 <code>restart: always</code>、systemd 的 <code>Restart=always</code>、OpenRC 的 <code>supervise-daemon</code>）都会自动拉起面板。自行运行时请确保进程退出后会被重新启动。</p></div><h3 id="第-1-步-检查备份" tabindex="-1">第 1 步：检查备份 <a class="header-anchor" href="#第-1-步-检查备份" aria-label="Permalink to &quot;第 1 步：检查备份&quot;">​</a></h3><ul><li><strong>从列表恢复：</strong> 在备份列表中点击某份备份的 <strong>恢复</strong>。</li><li><strong>从文件恢复：</strong> 点击 <strong>上传文件恢复</strong>，选择 <code>.nzbak</code> 文件（最大 256 MiB）。</li></ul><p>输入备份密码，或切换为恢复密钥，然后点击 <strong>检查备份</strong>。面板会下载并校验这份备份，包括校验值、解密、内容完整性、来源、版本兼容性、数据库完整性，以及是否存在管理员账号。</p><p><img src="'+n+'" alt="恢复预检"></p><p>检查结果会列出需要注意的情况，例如：</p><ul><li>备份之后新增的 Agent 会离线；</li><li>备份之后吊销的 API Token 和 OAuth 授权会重新生效；</li><li>TSDB 不会恢复，保持现状；</li><li>无法验证来源（不是本面板生成的备份）。</li></ul><p>其中部分警告需要勾选 <strong>我已了解，继续恢复</strong> 才能进行下一步。检查结果 10 分钟内有效，过期后需要重新检查。</p><h3 id="第-2-步-确认并执行" tabindex="-1">第 2 步：确认并执行 <a class="header-anchor" href="#第-2-步-确认并执行" aria-label="Permalink to &quot;第 2 步：确认并执行&quot;">​</a></h3><p>再次输入备份密码（或恢复密钥）、备份名的后 6 位，以及你的登录密码。只使用 OAuth 登录、没有本地密码的账号，需要在 10 分钟内重新登录过。</p><p><img src="'+i+'" alt="确认并执行"></p><p>点击 <strong>覆盖当前数据并重启面板</strong> 后：</p><ol><li>已配置存储和备份密码时，面板先自动备份一份当前数据，作为“恢复前自动”备份保留；</li><li>面板退出并重新启动，在打开数据库之前换入备份的数据；</li><li>页面会显示重启进度，面板恢复后跳转到登录页，使用<strong>备份中的账号</strong>登录。</li></ol><p>如果启动过程中出现数据库迁移错误、端口或 TLS 证书不可用，或者进程中途退出，面板会自动回滚到恢复前的数据。最近一次恢复的结果（成功、失败并已回滚）显示在备份页顶部。</p><p>为防止在线猜测密码，同一用户 15 分钟内最多进行 5 次检查或执行。所有备份和恢复操作都记录在数据目录下的 <code>backup-audit.log</code>。</p><h3 id="在新主机上恢复" tabindex="-1">在新主机上恢复 <a class="header-anchor" href="#在新主机上恢复" aria-label="Permalink to &quot;在新主机上恢复&quot;">​</a></h3><p>适用于迁移服务器，或原主机已经不可用的情况：</p><ol><li>在新主机上<a href="/guide/dashboard.html">安装 Dashboard</a>，版本不低于备份的版本（见下文的版本规则），并用安装时的默认管理员登录。</li><li>选择恢复方式： <ul><li><strong>有备份文件：</strong> 在备份页的“从备份文件恢复”中上传 <code>.nzbak</code> 文件，<strong>不需要先配置存储和密码</strong>；</li><li><strong>备份只在存储中：</strong> 先按<a href="#_1-配置-s3-存储">配置 S3 存储</a>填写原来的 bucket 和前缀，再从列表中恢复。</li></ul></li><li>输入原来的备份密码或恢复密钥，完成两步恢复。由于新主机上的密钥不同，检查结果会提示“无法验证来源”，确认文件可信后勾选继续即可。新主机还没有配置备份时，不会生成恢复前备份，页面会提示。</li><li>恢复后用原来的账号登录。<code>config.yaml</code> 也一并恢复，包括 Agent 的连接密钥，所以 Agent 只要还能连到原来的地址就会自动重连；如果地址变了，需要更新域名解析或 Agent 的连接地址。</li><li><strong>备份功能的设置不随备份恢复。</strong> 在新主机上重新配置存储、备份密码和定时计划。重新设置密码会生成新的密钥，存储中原有的备份会标为“旧密钥”，仍可以用原来的密码或恢复密钥恢复。</li></ol><div class="warning custom-block"><p class="custom-block-title">监听地址与证书</p><p>恢复后面板使用备份中的 <code>config.yaml</code>。启动时，生效的监听地址和端口必须能在新主机上绑定；启用 TLS 时，生效的证书和私钥文件必须可读，否则启动失败并自动回滚。端口或证书路径与原主机不同本身没有问题，按新主机的环境准备好即可，例如在相同路径放好证书，或调整 Docker 的端口映射。</p></div><p>新主机上线后，停用原主机的面板，避免两个面板同时执行任务和发送通知。如果原面板仍在运行并且使用同一个 bucket，请让两个面板使用不同的前缀。</p><h2 id="兼容性与版本规则" tabindex="-1">兼容性与版本规则 <a class="header-anchor" href="#兼容性与版本规则" aria-label="Permalink to &quot;兼容性与版本规则&quot;">​</a></h2><p>检查备份时，面板按核心版本号 <code>X.Y.Z</code> 比较备份与当前面板：</p><table tabindex="0"><thead><tr><th>情况</th><th>结果</th></tr></thead><tbody><tr><td>备份来自较旧的版本</td><td>可以恢复。启动时自动升级数据库结构，旧 <code>config.yaml</code> 中缺少的配置项使用默认值；升级失败时自动回滚。</td></tr><tr><td>版本相同</td><td>可以恢复。</td></tr><tr><td>核心版本相同、构建不同（版本号后缀不同）</td><td>需要勾选确认。不同构建之间可能有数据库差异，只有确认差异无害时才继续。</td></tr><tr><td>版本无法比较（例如开发构建）</td><td>需要勾选确认。</td></tr><tr><td>备份来自更高的核心版本</td><td><strong>拒绝恢复。</strong> 请先把面板升级到不低于备份的版本，再恢复。</td></tr></tbody></table><p>备份文件带有格式版本号，面板遇到无法识别的格式时会拒绝恢复，不会尝试读取。</p><h2 id="用环境变量设置存储" tabindex="-1">用环境变量设置存储 <a class="header-anchor" href="#用环境变量设置存储" aria-label="Permalink to &quot;用环境变量设置存储&quot;">​</a></h2><p>S3 存储的字段也可以用环境变量设置，适合用容器编排或密钥管理工具注入：</p><table tabindex="0"><thead><tr><th>环境变量</th><th>字段</th></tr></thead><tbody><tr><td><code>NZ_BACKUP_S3_ENDPOINT</code></td><td>Endpoint</td></tr><tr><td><code>NZ_BACKUP_S3_BUCKET</code></td><td>Bucket</td></tr><tr><td><code>NZ_BACKUP_S3_REGION</code></td><td>Region</td></tr><tr><td><code>NZ_BACKUP_S3_PREFIX</code></td><td>对象键前缀</td></tr><tr><td><code>NZ_BACKUP_S3_ACCESS_KEY_ID</code></td><td>Access Key ID</td></tr><tr><td><code>NZ_BACKUP_S3_SECRET_ACCESS_KEY</code></td><td>Secret Access Key</td></tr></tbody></table><p>由环境变量设置的字段在页面上显示为“由环境变量设置”，不能在后台修改。Secret 由环境变量提供时，Endpoint 和 Bucket 也是只读的，避免把密钥发往后台填写的其它地址。备份功能的其它设置保存在数据目录下单独的 <code>backup.yaml</code>（权限 0600），不写入 <code>config.yaml</code>。这些变量名与 <code>config.yaml</code> 字段的<a href="/configuration/environment.html">环境变量命名规则</a>不同，按上表填写即可。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>和手动备份数据目录有什么区别？</strong> 内置备份不需要停机，自动加密并上传到异地存储，恢复时有校验和失败回滚。它只覆盖面板本身。需要同时迁移 TSDB 或部署文件，或者面板版本还没有这个功能时，使用<a href="/guide/q5.html">手动方法</a>。</p><p><strong>恢复后 Agent 显示离线？</strong> 备份之后新增的 Agent 在备份的数据中不存在，需要重新添加。其余 Agent 会自动重新连接；如果面板地址变了，需要更新 Agent 的连接地址。</p><p><strong>面板执行恢复后没有自动回来？</strong> 检查面板是否由守护进程管理，然后手动启动。换入在启动时完成，不需要其它操作。</p>',66)])])}const S=e(p,[["render",h]]);export{f as __pageData,S as default};
